/**
 * Uploads file buffers to the Rayvn /files endpoint.
 *
 * Reads file metadata from msg.entry.files and fetches buffers from global context
 * via context_key. Files without a context_key are treated as upload failures —
 * they have no buffer because the download previously failed, and are recorded
 * explicitly rather than skipped silently.
 *
 * Upload failures are added to msg.metadata.failed_files. Since msg.metadata and
 * entry.metadata are the same object (set by Bridge to Rayvn), this is
 * consistent regardless of which reference is used further in the flow.
 *
 * On completion: msg.payload.files = array of Rayvn file IDs.
 */
const target  = msg.metadata.target;
const baseUrl = global.get("parat_bridge").base_urls.rayvn;
const utils   = global.get("utils");
const files   = (msg.entry && msg.entry.files) || [];

// No files to upload — clear payload.files and continue
if (files.length === 0) {
    msg.payload.files = [];
    return msg;
}

const resolved = [];
const failed   = [];

for (const file of files) {
    // Missing context_key means the download never succeeded.
    // Record as upload failure so it appears in the final failure picture.
    if (!file.context_key) {
        failed.push({ name: file.name || "unknown file", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        continue;
    }

    const buffer = global.get("files." + file.context_key);

    if (!buffer || buffer.length === 0) {
        node.warn("No buffer found for context_key: " + file.context_key);
        failed.push({ name: file.name || "unknown file", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        continue;
    }

    try {
        const boundary = "----PBBoundary" + Date.now();
        const header   = `--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="${file.name || "file.bin"}"\r\nContent-Type: ${file.type || "application/octet-stream"}\r\n\r\n`;
        const footer   = `\r\n--${boundary}--\r\n`;
        const body     = Buffer.concat([Buffer.from(header), buffer, Buffer.from(footer)]);

        const res = await nodeFetch(baseUrl + "/files", {
            method:  "POST",
            headers: {
                "Authorization": "Bearer " + target.api_key,
                "Content-Type":  "multipart/form-data; boundary=" + boundary
            },
            body
        });

        if (res.ok) {
            const data = await res.json();
            resolved.push(data.id);
            node.log(`File uploaded: ${file.name} → ${data.id}`);
        } else {
            node.warn(`Rayvn /files returned ${res.status} for ${file.name}`);
            failed.push({ name: file.name || "unknown file", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        }
    } catch (e) {
        node.warn(`Error uploading ${file.name}: ${e.message}`);
        failed.push({ name: file.name || "unknown file", reason: utils.FILE_REASONS.UPLOAD_FAILED });
    }
}

// Replace entry files with Rayvn file IDs ready for POST
msg.payload.files = resolved;

// Add upload failures to metadata.failed_files (= entry.metadata.failed_files)
if (failed.length > 0) {
    msg.metadata.failed_files = [
        ...(msg.metadata.failed_files || []),
        ...failed
    ];
}

return msg;

/**
 * Patches msg.payload.text with a receiver notice based on the complete failure picture.
 *
 * Runs after all upload attempts — metadata.failed_files now contains
 * classify failures, download failures, and upload failures combined.
 *
 * msg.payload.files contains Rayvn file IDs after successful upload,
 * and is used to calculate the correct number of successful transfers.
 *
 * No failures → msg passes through unchanged.
 */
const failed = msg.metadata.failed_files || [];

if (failed.length === 0) return msg;

const succeeded = msg.payload.files.length;
const total     = succeeded + failed.length;
const notice    = " [" + failed.length + "/" + total
                + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";

msg.payload.text = (msg.payload.text || "") + notice;

return msg;
